/* global jQuery */

var ibis = window.ibis || window.parent.ibis;

var ibisPopup = {
    getParam: function (n, dv) {
        return this.editor.getParam(n, dv);
    },
    getLang: function (n, dv) {
        return this.editor.getLang(n, dv);
    },
    getWindowArg: function (n, dv) {
        var v = this.editor.windowManager.params[n];
        return (typeof v !== "undefined") ? v : dv;
    },
    close: function () {
        return this.editor.windowManager.close();
    }
};

// fake editor
ibisPopup.editor = ibis;

jQuery(document).ready(function ($) {
    var win = window.parent,
        s = ibisPopup.editor.settings,
        el;

    if (s.element) {
        el = win.document.getElementById(s.element);

        if (el) {
            ibisPopup.editor.windowManager.params.value = el.value;
        }
    }

    if (s.callback) {
        var fn = win[s.callback];

        if (typeof fn === "function") {
            ibisPopup.editor.windowManager.params.callback = fn;
        }
    }

    if (!el && !s.callback && !s.element) {
        $('#cancel, #insert').hide();
    }
});